style.css:
/* ==UserStyle==
@name MercadoLibre Argentina - Gris Oscuro
@namespace mercadolibre
@version 1.0.0
@description Convierte el fondo blanco en gris y los grises en más oscuros.
@match *://www.mercadolibre.com.ar/*
==/UserStyle== */

body, 
html, 
div, 
section, 
header, 
footer, 
main, 
article {
    background-color: #e0e0e0 !important; /* reemplazo del blanco por gris claro */
    color: #111 !important; /* texto más oscuro para contraste */
}

* {
    /* Reemplazo de grises actuales por un gris más oscuro */
    background-color: #cccccc !important; /* gris claro original → más oscuro */
    border-color: #999999 !important; 
}

input, textarea, select {
    background-color: #d6d6d6 !important;
    color: #111 !important;
}

a {
    color: #0044cc !important; /* mantiene enlaces legibles */
}
